<script setup>
import {useSpace,readSpaceChoice,writeSpaceChoice} from "../space-context.js";
const space=useSpace(),songcai=space.api;
import { computed, nextTick, onMounted, ref, watch } from 'vue';
import { MARKETS, formatMoney, pad } from '../core/rules.js';
import DrawComparison from './DrawComparison.vue';
import DrawBalls from './DrawBalls.vue';
import RebateBreakdown from './RebateBreakdown.vue';
import {rebateRateLabel} from '../core/rebates.js';
import { verifyDraws } from '../core/draw-verification.js';
import { DRAW_SOURCES, DRAW_REFERENCES } from '../core/draws.js';
import { RATE_ROWS } from '../core/settlement.js';
import { browserSettlement } from '../settlement-preview.js';
const props=defineProps({documents:Array,parsedDocuments:Array,activeId:String,initialDate:String,prepare:Function,active:Boolean});
const emit=defineEmits(['updated','rebates']);
const api=songcai?.settlement||browserSettlement(()=>props.documents,space.id);
const desktop=!!songcai;
const choiceKey='songcai.settlement.choice',choice=readSpaceChoice(choiceKey,space.id);
const date=ref(choice.date||props.initialDate),kind=ref(choice.kind||'current'),settings=ref(null),draws=ref({新:[],旧:[],港:[]}),drawIds=ref(choice.ids||{新:'',旧:'',港:''});
const busy=ref(false),error=ref(''),message=ref(''),reports=ref([]),preview=ref(null),reviewed=ref(false),history=ref([]),savedView=ref(null),showSettings=ref(false),oddsMarket=ref('新'),oddsSearch=ref(''),settingsDirty=ref(false),loadedSettings=ref('');
const manualMarket=ref('新'),manualIssue=ref(''),manualNumbers=ref(''),manualSource=ref('人工核对'),showManual=ref(false),detailMarket=ref(''),detailPlayer=ref(''),detailState=ref(''),page=ref(1);
const decisions=ref(choice.decisions||{}),manualReference=ref('');
watch([date,kind,drawIds,decisions],()=>writeSpaceChoice(choiceKey,space.id,{date:date.value,kind:kind.value,ids:drawIds.value,decisions:decisions.value}),{deep:true});
const liveVerification=computed(()=>settings.value?verifyDraws(draws.value,settings.value,date.value,drawIds.value,decisions.value,reports.value):null);
const verification=computed(()=>savedView.value?savedView.value.inputs.verification:liveVerification.value);
const unverifiedMarkets=computed(()=>[...new Set(preview.value?.result.entries.map(e=>e.market)||[])].filter(m=>!preview.value?.inputs.verification[m]?.confirmed));
const inputs=()=>({date:date.value,kind:kind.value,activeId:props.activeId,decisions:JSON.parse(JSON.stringify(decisions.value)),drawIds:JSON.parse(JSON.stringify(drawIds.value))});
const display=computed(()=>savedView.value?.result||preview.value?.result);
const selected=computed(()=>savedView.value?.inputs.draws||Object.fromEntries(MARKETS.map(m=>[m,draws.value[m].find(d=>d.id===drawIds.value[m])])));
const unconfirmedMarkets=computed(()=>[...new Set(preview.value?.result.entries.map(e=>e.market)||[])].filter(m=>!preview.value?.settings.odds[m].confirmed));
const enabledRates=computed(()=>RATE_ROWS.filter(row=>`${row.label} ${row.key}`.includes(oddsSearch.value)));
const displayEntries=computed(()=>(display.value?.entries||[]).filter(e=>(!detailMarket.value||e.market===detailMarket.value)&&(!detailPlayer.value||(e.playerId||e.player)===detailPlayer.value)&&(!detailState.value||e.status===detailState.value)));
const currentEntries=computed(()=>displayEntries.value.slice((page.value-1)*50,page.value*50));
const totalPages=computed(()=>Math.max(1,Math.ceil(displayEntries.value.length/50)));
const scopeLabels={'flat-number':'平码','flat-zodiac':'平特肖','flat-tail':'平特尾','linked-zodiac':'连肖','linked-tail':'连尾','not-hit':'不中'};
const statusLabels={won:'中奖',lost:'未中奖',refund:'退本金',pending:'待结算'};
const kindLabels={current:'当前账目',ledger:'该日期全部账目',inbox:'微信已入账记录'};
const money=formatMoney;
function resetPreview(){preview.value=null;savedView.value=null;reviewed.value=false;page.value=1;}
async function action(fn){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function load(){const data=await api.load({date:date.value});settings.value=data.settings;loadedSettings.value=JSON.stringify(data.settings);draws.value=data.draws;reports.value=data.reports||[];history.value=data.history;settingsDirty.value=false;for(const m of MARKETS)if(!draws.value[m].some(d=>d.id===drawIds.value[m]&&d.date===date.value))drawIds.value[m]='';}
async function saveSettings(){await action(async()=>{settings.value=await api.settings(JSON.parse(JSON.stringify(settings.value)));loadedSettings.value=JSON.stringify(settings.value);settingsDirty.value=false;resetPreview();message.value='赔率与来源已保存；已有赔付快照保留原配置。';emit('updated');});}
async function sync(){await action(async()=>{if(settingsDirty.value)throw new Error('请先保存来源和赔率设置');reports.value=await api.sync({date:date.value});await load();resetPreview();message.value='已完成来源查询，请为各市场选择与业务日期一致的完整开奖。';});}
async function manual(){await action(async()=>{if(settingsDirty.value)throw new Error('请先保存来源和赔率设置');await api.manual({market:manualMarket.value,issue:manualIssue.value,date:date.value,numbers:manualNumbers.value,sourceName:manualSource.value,referenceId:manualReference.value});await load();resetPreview();showManual.value=false;message.value='手动开奖已保存，请在对应市场选择此期；不会覆盖原开奖记录。';});}
async function calculate(){await action(async()=>{if(settingsDirty.value)throw new Error('请先保存赔率设置');await props.prepare?.();preview.value=await api.preview(inputs());savedView.value=null;reviewed.value=false;page.value=1;});}
async function confirm(){await action(async()=>{if(!preview.value)throw new Error('请先计算');await props.prepare?.();const record=await api.save({...inputs(),inputHash:preview.value.inputHash,reviewed:reviewed.value});savedView.value=record;history.value=(await api.load({date:date.value})).history;message.value=record.reused?'此版本已保存，未重复新增。':'赔付计算已保存；尚未标记付款。';});}
async function openHistory(id){await action(async()=>{savedView.value=await api.get({id});page.value=1;});}
async function exportSnapshot(){await action(async()=>{const record=savedView.value||preview.value;if(!record)throw new Error('请先计算或选择已保存记录');const text=JSON.stringify(record,null,2);if(songcai){if(await songcai.saveFile(`松财赔付-${date.value}.json`,text))message.value='已导出赔付计算、原文、开奖与赔率依据。';}else{const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`松财赔付-${date.value}.json`;a.click();URL.revokeObjectURL(url);}});}
async function adopt(m,id){drawIds.value[m]=id;await nextTick();decisions.value={...decisions.value,[m]:{drawId:id,reviewKey:liveVerification.value[m].reviewKey}};message.value=`已采用${m}市场所选结果；请重新计算赔付。`;}
async function openSource(id){await action(()=>api.openSource({id}));}
watch(decisions,resetPreview,{deep:true});
watch([date,kind,drawIds,()=>props.activeId],resetPreview,{deep:true});
watch(date,()=>{reports.value=[];action(load);});
watch(()=>props.documents,()=>{if(preview.value)resetPreview();},{deep:true});
watch(settings,()=>{settingsDirty.value=!!settings.value&&JSON.stringify(settings.value)!==loadedSettings.value;if(settingsDirty.value)resetPreview();},{deep:true});
watch(()=>JSON.stringify(settings.value?.sources),(_,previous)=>{if(previous)drawIds.value={新:'',旧:'',港:''};});
watch([detailMarket,detailPlayer,detailState],()=>{page.value=1;});
async function flush(){if(busy.value)throw new Error('开奖赔付正在处理，请稍候再切换空间');if(settingsDirty.value){settings.value=await api.settings(JSON.parse(JSON.stringify(settings.value)));loadedSettings.value=JSON.stringify(settings.value);settingsDirty.value=false;}}
defineExpose({flush});
watch(()=>props.active,active=>{if(active&&!settingsDirty.value)action(async()=>{const previous=loadedSettings.value,recalculate=!!preview.value&&!savedView.value;await load();if(previous!==loadedSettings.value&&!savedView.value){resetPreview();if(recalculate){await props.prepare?.();preview.value=await api.preview(inputs());}}});});
onMounted(()=>action(load));
</script>

<template>
  <div class="page-body settlement-page">
    <section class="page-heading"><div><div class="eyebrow">DRAW RESULTS & PAYOUTS</div><h1>开奖与赔付</h1><p>按业务日期和市场核对开奖，计算每位玩家的应付金额。</p></div><button class="button" @click="showSettings=!showSettings">{{showSettings?'收起赔率设置':'赔率与来源设置'}}</button></section>
    <div class="settlement-toolbar"><label>结算业务日期<input v-model="date" type="date" min="2000-01-01" max="2100-12-31" :disabled="busy||settingsDirty" /></label><label>投注来源<select v-model="kind" :disabled="busy"><option value="current">当前账目</option><option value="ledger">该日期全部账目</option><option value="inbox" :disabled="!desktop">微信已入账记录</option></select></label><button class="button primary" :disabled="busy||!settings" @click="sync">{{busy?'处理中…':'获取开奖记录'}}</button><button class="button" :disabled="busy" @click="showManual=!showManual">手动录入开奖</button></div>
    <button class="text-button rebate-settings-link" @click="$emit('rebates')">玩家退水设置 ↗</button>
    <p class="settlement-note">各市场独立选择同一天的开奖，绝不把“最新一期”自动套到其他日期。当前账目只包含当前打开的原文；微信已入账记录单独计算，避免重复计入。</p>
    <p v-if="error" class="settlement-error" role="alert">{{error}}</p><p v-if="message" class="settlement-success" role="status">{{message}}</p>
    <section v-if="settings&&showSettings" class="panel settlement-settings">
      <h2>开奖来源（可多选）</h2><p class="settlement-note">“新／旧”名称可能对应不同频道，请按你使用的网站选择。来源失败会保留本地历史；更换来源后请重新选择期号。</p>
      <div class="source-settings"><fieldset v-for="m in MARKETS" :key="m" :disabled="busy"><legend>{{m}}市场</legend><label v-for="source in DRAW_SOURCES.filter(s=>s.markets.includes(m)&&!s.retired)" :key="source.id" class="source-choice"><span><input v-model="settings.sources[m]" type="checkbox" :value="source.id" />{{source.name}}</span><small>{{source.note}}</small></label></fieldset></div>
      <p class="settlement-note">已按用户确认的号码识别新、老澳门和香港频道；22:32“澳门”和1234“㊣澳门”不对应用户的旧市场，已排除。多个网页引用相同接口只计一组数据。</p>
      <div v-for="reference in DRAW_REFERENCES" :key="reference.id" class="reference-source"><strong>{{reference.name}}</strong><span>{{reference.note}}</span><button class="text-button" @click="openSource(reference.id)">打开参考网站 ↗</button></div>
      <h2>各市场赔率与中奖范围</h2><div class="odds-config-heading"><select v-model="oddsMarket" aria-label="设置哪个市场赔率"><option v-for="m in MARKETS" :key="m" :value="m">{{m}}市场</option></select><span>原图预填：特码47倍，赔率含本金。未填赔率的中奖项目保持待结算。</span></div>
      <div class="odds-options"><label>赔率口径<select v-model="settings.odds[oddsMarket].includePrincipal"><option :value="true">含本金（100 × 2.7 = 应付270）</option><option :value="false">净赢赔率（100 × 2.7 + 100 = 应付370）</option></select></label><label>特殊生肖低赔率<select v-model="settings.odds[oddsMarket].specialAnimal"><option value="lunar">随开奖日期的农历年切换</option><option value="马">固定使用马</option></select></label><label v-for="(label,key) in scopeLabels" :key="key">{{label}}中奖范围<select v-model="settings.odds[oddsMarket].scopes[key]"><option value="six">前6个正码</option><option value="seven">全部7个（含特码）</option></select></label><label>平特任中中奖范围<select aria-label="平特任中中奖范围" value="seven" disabled><option value="seven">全部7个（含特码）</option></select></label></div>
      <p class="settlement-note">连肖／连尾：每组所有选项均出现才中；平特肖／尾：同一肖或尾出现多次仍按一份；平特任中：固定看全部7个开奖号码（含特码），每组任一号码出现即中，多号命中仍按一组赔付；全不中：每组所选均未出现；三中二两档互斥，不叠加。明确写“平特号码”的原文使用全部7个。</p>
      <div class="odds-options"><label v-for="(label,key) in {attribute:'大小单双／合单合双',sixZodiac:'六肖中特',halfWave:'半波'}" :key="key">特码49时 · {{label}}<select v-model="settings.odds[oddsMarket].refund49[key]"><option :value="null">待确认</option><option :value="true">和局退本金</option><option :value="false">正常判断输赢</option></select></label></div>
      <input v-model="oddsSearch" class="settlement-search" aria-label="筛选赔付赔率" placeholder="搜索玩法赔率…" />
      <div class="rate-table-wrap"><table class="settlement-table"><thead><tr><th>玩法</th><th>普通赔率</th><th>特殊生肖／有当年生肖</th></tr></thead><tbody><tr v-for="r in enabledRates" :key="r.key"><td>{{r.label}}</td><td><input :aria-label="r.label+'普通赔率'" v-model="settings.odds[oddsMarket].rates[r.key].rate" inputmode="decimal" placeholder="待配置" /></td><td><input v-if="r.specialRate" :aria-label="r.label+'特殊赔率'" v-model="settings.odds[oddsMarket].rates[r.key].specialRate" inputmode="decimal" placeholder="待配置" /><span v-else>—</span></td></tr></tbody></table></div>
      <div class="settings-save"><label><input type="checkbox" v-model="settings.odds[oddsMarket].confirmed" />已核对{{oddsMarket}}市场的赔率、中奖范围和和局规则</label><button class="button primary" :disabled="busy" @click="saveSettings">保存赔率与来源</button><small v-if="settingsDirty">有未保存修改</small></div>
    </section>
    <section v-if="showManual" class="panel manual-draw"><h2>手动录入完整开奖</h2><div class="odds-options"><label>市场<select v-model="manualMarket"><option v-for="m in MARKETS" :key="m">{{m}}</option></select></label><label>期号<input v-model="manualIssue" placeholder="例如2026277" /></label><label>参考网站<select v-model="manualReference"><option value="">其他／人工核对</option><option v-for="r in DRAW_REFERENCES" :key="r.id" :value="r.id">{{r.name}}（人工录入）</option></select></label><label v-if="!manualReference">核对来源<input v-model="manualSource" placeholder="来源名称或备注" /></label></div><label>前6个平码，最后1个特码<input v-model="manualNumbers" class="manual-numbers" aria-label="手动开奖号码" placeholder="例如 41 23 14 31 13 32 + 11" /></label><p class="settlement-note">日期：{{date}}。只保存完整且互不重复的7个号码；已有同一期记录保留原版本。</p><button class="button" :disabled="busy" @click="manual">保存手动开奖</button></section>
    <details v-if="reports.length" class="sync-reports"><summary>最近一次各网站查询结果（{{reports.length}}项）</summary><p v-for="r in reports" :key="r.market+':'+r.sourceId" :class="{'settlement-error':!r.ok}">{{r.market}} · {{r.sourceName}}：{{r.message}}<span v-if="r.latest"> · 来源最近：{{r.latest.date}}／{{r.latest.issue}}</span></p></details>
    <div class="draw-card-grid"><section v-for="m in MARKETS" :key="m" class="panel draw-card"><header><h2>{{m}}市场开奖</h2><span>{{date}}</span></header><p v-if="savedView">已保存期号：{{selected[m]?.issue || '此市场无投注'}}</p><select v-else v-model="drawIds[m]" :aria-label="m+'市场开奖期号'" :disabled="busy"><option value="">请选择当日开奖</option><option v-for="d in draws[m].filter(d=>d.date===date&&!DRAW_SOURCES.find(s=>s.id===d.sourceId)?.retired)" :key="d.id" :value="d.id">{{d.issue}} · {{d.sourceName}} · 特码{{pad(d.numbers[6])}}</option></select><template v-if="selected[m]"><DrawBalls class="market-draw-balls" :numbers="selected[m].numbers" :date="selected[m].date" compact /><p>{{selected[m].sourceName}}</p><small>{{selected[m].openedAt?new Date(selected[m].openedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):selected[m].date}} · 获取于 {{new Date(selected[m].observedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</small><p v-if="verification?.[m]?.status==='conflict'" class="settlement-error">{{savedView?'保存时存在差异，已按用户采用的结果结算。':'同一期存在不同号码记录，请核对来源再结算。'}}</p></template><p v-else-if="savedView" class="draw-empty">此版本未使用该市场开奖。</p><p v-else class="draw-empty">尚未选择 {{date}} 的开奖。<span v-if="draws[m].length">本地最近记录为 {{draws[m][0].date}}，不会自动代用。</span></p></section></div>
    <template v-if="verification"><DrawComparison v-for="m in MARKETS" :key="m" :comparison="verification[m]" :busy="busy||settingsDirty" :readonly="!!savedView" @adopt="id=>adopt(m,id)" @open="openSource" /></template><p v-else-if="savedView" class="settlement-note">此旧版快照未保存多站核对依据，原计算结果保留。</p>
    <div class="settlement-actions"><button v-if="savedView" class="button primary" :disabled="busy" @click="resetPreview">返回当前结算</button><button v-else class="button primary" :disabled="busy||!settings||settingsDirty" @click="calculate">计算玩家赔付</button><span>金额为应付计算，包含赔付、应退本金和退水；不代表已经付款。</span></div>
    <template v-if="display">
      <div v-if="!savedView&&unverifiedMarkets.length" class="settlement-error">仅试算：{{unverifiedMarkets.join('、')}}市场尚未完成开奖核对。请在网站核对列表中选择并采用结果。</div>
      <div v-if="!savedView&&unconfirmedMarkets.length" class="settlement-error">当前为试算，{{unconfirmedMarkets.join('、')}}市场的赔率与中奖范围尚未确认。<button class="text-button" @click="showSettings=true">打开赔率设置</button></div>
      <div v-if="savedView" class="saved-banner">正在查看已保存版本：{{new Date(savedView.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}} · {{kindLabels[savedView.inputs.kind]}}。修改原文或赔率不会改写此版本。</div>
      <section class="settlement-metrics"><div><small>本次投注</small><strong>¥ {{money(display.stakeCents)}}</strong></div><div><small>{{display.complete?'应付合计':'已算出应付（未完成）'}}</small><strong>¥ {{money(display.payableCents??display.payoutCents)}}</strong></div><div><small>其中退水</small><strong>¥ {{money(display.rebateCents||0)}}</strong></div><div><small>其中退本金</small><strong>¥ {{money(display.refundCents)}}</strong></div><div><small>待结算／原文问题</small><strong>{{display.pending}} / {{display.issues.length}}</strong></div></section>
      <div v-if="display.issues.length" class="settlement-error">原文仍有问题：<p v-for="issue in display.issues.slice(0,10)" :key="issue.id">{{issue.document}} 第{{issue.line}}行：{{issue.message}}</p></div>
      <section class="panel payout-summary"><h2>每日玩家结算</h2><p class="settlement-note">应付＝赔付＋退水；玩家净输赢＝应付－投注。未完成结算的退水仅含已结算部分。</p><div class="table-scroll"><table class="settlement-table"><thead><tr><th>玩家</th><th v-for="m in MARKETS" :key="m">{{m}}市场应付</th><th>应付合计</th><th>投注 / 有效流水</th><th>退水率 / 退水</th><th>玩家净输赢</th></tr></thead><tbody><tr v-for="p in display.players" :key="p.id||p.name"><th>{{p.name}}</th><td v-for="m in MARKETS" :key="m">{{money(p.markets[m].payableCents??p.markets[m].payoutCents)}}<small v-if="p.markets[m].pending"> + {{p.markets[m].pending}}笔待结算</small></td><td>{{money(p.payableCents??p.payoutCents)}}<small v-if="p.pending">未完成</small></td><td>{{money(p.stakeCents)}}<small>流水 {{money(p.turnoverCents||0)}}</small></td><td>{{rebateRateLabel(p)}}<small>退水 {{money(p.rebateCents||0)}}</small></td><td>{{p.pending||display.issues.length?'待结算':money((p.payableCents??p.payoutCents)-p.stakeCents)}}</td></tr></tbody></table></div></section>
      <RebateBreakdown :players="display.players" />
      <section class="panel payout-details"><div class="payout-detail-heading"><h2>赔付明细</h2><select v-model="detailMarket" aria-label="筛选赔付市场"><option value="">全部市场</option><option v-for="m in MARKETS" :key="m">{{m}}</option></select><select v-model="detailPlayer" aria-label="筛选赔付玩家"><option value="">全部玩家</option><option v-for="p in display.players" :key="p.id||p.name" :value="p.id||p.name">{{p.name}}</option></select><select v-model="detailState" aria-label="筛选赔付状态"><option value="">全部状态</option><option v-for="(label,key) in statusLabels" :key="key" :value="key">{{label}}</option></select></div><p v-if="!display.entries.length" class="draw-empty">所选来源没有 {{date}} 的投注。</p><details v-for="entry in currentEntries" :key="entry.id" class="payout-entry"><summary><span>{{entry.player}} · {{entry.market}} · {{entry.play}}</span><small :class="entry.status">{{statusLabels[entry.status]}}</small><strong>{{entry.payoutCents===null?'—':money(entry.payoutCents)}}</strong></summary><div><p class="payout-raw">{{entry.raw}}</p><p>{{entry.fileName}} 第{{entry.line}}行 · {{entry.issue||'未选开奖'}} · 投注 {{money(entry.stakeCents)}}元</p><p>{{entry.note}}</p><p v-for="(tier,i) in entry.tiers" :key="i">{{tier.count}}份 × 每份应付{{money(tier.unitPayoutCents)}}元（赔率{{tier.rate}}{{tier.yearAnimal?'，有'+tier.yearAnimal:''}}）＝ {{money(tier.payoutCents)}}元</p></div></details><div class="pagination"><span>{{displayEntries.length}}笔</span><button :disabled="page===1" @click="page--">上一页</button>{{page}} / {{totalPages}}<button :disabled="page===totalPages" @click="page++">下一页</button></div></section>
      <div v-if="!savedView" class="settlement-confirm"><label><input type="checkbox" v-model="reviewed" :disabled="!display.complete" />已核对各市场开奖来源、期号、号码及账目范围</label><button class="button primary" :disabled="busy||!display.complete||!reviewed||unconfirmedMarkets.length||unverifiedMarkets.length" @click="confirm">保存赔付记录</button></div><button class="button" :disabled="busy" @click="exportSnapshot">导出本次计算与依据</button>
    </template>
    <div v-if="savedView?.parserReview?.required" class="settlement-error">{{savedView.parserReview.message}}<p v-if="savedView.parserReview.beforePayoutCents!=null">原应付 {{money(savedView.parserReview.beforePayoutCents)}}元 → 新解释应付 {{savedView.parserReview.afterPayoutCents==null?'待处理':money(savedView.parserReview.afterPayoutCents)+'元'}}</p><details v-if="savedView.parserReview.documents"><summary>查看受影响原文</summary><div v-for="d in savedView.parserReview.documents" :key="d.id">{{d.name}}：<p v-for="c in d.changes" :key="c.line">第{{c.line}}行 · {{c.before.map(b=>b.play+'／'+b.basis+'／'+money(b.totalCents)+'元').join('；')||'无投注'}} → {{c.after.map(b=>b.play+'／'+b.basis+'／'+money(b.totalCents)+'元').join('；')||'待处理'}}</p></div></details></div><section class="panel settlement-history"><h2>{{date}} 已保存的赔付版本</h2><p class="settlement-note">相同输入重复保存不新增。重新计算保留独立版本，历史版本不会相加。</p><button v-for="h in history" :key="h.id" class="history-item" :disabled="busy" @click="openHistory(h.id)"><span>{{new Date(h.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}} · {{kindLabels[h.kind]}} · {{h.entries}}笔</span><strong>应付 {{money(h.payableCents??h.payoutCents)}}元 <small v-if="h.parserReviewRequired">· 解析变化待复核</small></strong></button><p v-if="!history.length" class="draw-empty">尚无保存记录。</p></section>
  </div>
</template>

